/* UI-chrome translations (labels, buttons, placeholders, statuses).
   Database content (articles, quiz questions, escalation notes, AI answers) is
   never translated here. English is the source of truth: any key that is
   missing from zh/ms falls back to the English string at runtime. */

export const SUPPORTED_LANGUAGES = ['en', 'zh', 'ms'];
export const DEFAULT_LANGUAGE = 'en';

// Name shown in the selector (always in its own language) plus a compact code.
export const LANGUAGE_OPTIONS = [
  { code: 'en', short: 'EN', label: 'English', htmlLang: 'en' },
  { code: 'zh', short: '中文', label: '简体中文', htmlLang: 'zh-Hans' },
  { code: 'ms', short: 'BM', label: 'Bahasa Melayu', htmlLang: 'ms' },
];

